/// <summary>
/// CB 797 send PE pricing Data contract class for service <c>METPriceComponentDetailContract</c>
/// </summary>
[DataContractAttribute]
public class METPriceComponentDetailContract
{
    InventTransId            inventTransId;
    DataAreaId               dataAreaId;
    METPriceCodeRef          priceCodeRef;
    METComponent             component;
    METComponentCodeId       codeId;
    Amount                   customerAllowance, vendorAllowance;
    METReference             reference;
    FromDate                 fromDate;
    ToDate                   toDate;

}

Method.Source:
/// <summary>
/// Gets/sets the company ID
/// </summary>
/// <param name = "_dataAreaId">company ID</param>
/// <returns>returns the company ID</returns>
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
